@startuml

class Customer {
  + name : string
  + accountDetails : string
}

class Broker {
  + name : string
}

class HeadOffice {}

class InsuranceProduct {
  + price : float
}

class Contract {
  + offerDate : date
  + signingDate : date
  + billingCycle : string
}

class ClaimCase {
  + status : string
}

class ClaimReport {
  + reportDate : date
  + content : string
}

class CompensationDecision {
  + eligibleCosts : float
  + totalSum : float
}

class Estimator {
  + name : string
  + expertise : string
}

Customer "1" -- "0..*" Contract : signs
Customer "1" -- "0..*" ClaimCase : files
Customer "1" -- "0..1" Broker : assigned to
Broker "1" -- "*" Customer : follows
HeadOffice -- "*" Broker : employs
HeadOffice -- "*" Estimator : employs
Contract "1" -- "1" InsuranceProduct : based on
Contract "1" *-- "0..*" ClaimCase : generates
ClaimCase "1" -- "1..*" ClaimReport : involves
ClaimCase "1" -- "0..1" CompensationDecision : results in
Estimator "1..*" -- "*" ClaimReport : issues
Estimator "1..*" -- "*" ClaimCase : assesses

@enduml

